import {icon,esc} from './ui.js';
import {examples,iteratorExperiment,playgroundURL} from './examples.js';
const groups={ownership:['Ownership','One value. One owner. A clear story.'],borrowing:['Borrowing','Access without taking ownership.'],lifetimes:['Lifetimes','A reference is only useful while its data lives.'],iterators:['Iterators','Small transformations. A useful pipeline.']};
let root,timer,current,frame=0,playing=false,group='ownership',pipeline;
export function destroyLab(){clearInterval(timer);playing=false;root=null;}
export function redrawLab(){}
export function mountLab(container,type='ownership'){
 destroyLab();root=container;group=groups[type]?type:'ownership';current=examples.find(e=>e.group===group);frame=0;
 root.innerHTML=`<div class="page-heading"><div><div class="eyebrow">LESS GUESSING. MORE UNDERSTANDING.</div><h1>Your very own Rust workbench.</h1><p>${groups[group][1]}</p></div><button class="btn" id="download-rust">${icon('file')} Download .rs</button></div><div class="model-tabs">${Object.entries(groups).map(([id,[label]])=>`<button class="model-tab ${id===group?'active':''}" data-lab="${id}">${icon(id==='ownership'?'database':id==='borrowing'?'rows':id==='lifetimes'?'clock':'signal')}${label}</button>`).join('')}</div><div id="lab-body"></div>`;
 root.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>location.hash='#/lab/'+b.dataset.lab);
 root.querySelector('#download-rust').onclick=()=>{const code=group==='iterators'?pipeline?.code:current.code;if(!code)return;const url=URL.createObjectURL(new Blob([code],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='rust-school-'+(group==='iterators'?'pipeline':current.id)+'.rs';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 if(group==='iterators')renderIterator();else renderTrace();
}
function renderTrace(){const options=examples.filter(e=>e.group===group);root.querySelector('#lab-body').innerHTML=`<div class="trace-layout"><aside class="lab-controls"><h2>${icon('list')} Choose an example</h2><div class="scenario-list">${options.map(e=>`<button class="scenario-btn ${e.id===current.id?'active':''}" data-example="${e.id}"><span>${esc(e.name)}</span><small>${e.error?'Rejected · '+e.error:'Valid Rust'}</small></button>`).join('')}</div><p class="lab-explanation">${esc(current.summary)}</p><div class="trace-help">Step through the reasoning. These curated programs were checked with rustc. The visual trace is a teaching model, not a live compiler.</div><a class="btn" href="${esc(playgroundURL(current.code))}" target="_blank" rel="noopener noreferrer">${icon('code')} Rust Playground</a></aside><div class="lab-content"><div class="trace-toolbar"><div class="compiler-state ${current.error?'rejected':'accepted'}">${icon(current.error?'x':'check')} ${current.error?'Compiler rejects · '+current.error:'Compiler checked · valid Rust'}</div><span class="engine-indicator">Rust 2024</span></div><div class="trace-grid"><section class="plot-card"><div class="panel-heading"><span>${icon('code')} main.rs</span><small>complete example</small></div><pre class="trace-code" id="trace-code"></pre><div class="trace-controls"><button class="btn" id="trace-back">Back</button><button class="btn primary" id="trace-next">Next step</button><button class="btn" id="trace-play" aria-label="Play trace">${icon('play')}</button><button class="btn" id="trace-reset" aria-label="Reset trace">${icon('replay')}</button></div></section><section class="plot-card"><div class="panel-heading"><span>${icon('database')} Memory & access</span><small>conceptual view</small></div><div id="memory-view"></div></section></div><section class="trace-explanation" aria-live="polite" id="trace-explanation"></section><section class="output-card"><div class="panel-heading"><span>${icon('terminal')} ${current.error?'Compiler diagnostic':'Expected stdout'}</span><small>${current.error?'Program does not run':'Verified output for this example'}</small></div><pre id="trace-output" class="trace-output"></pre></section><p class="query-note">No Rust compiler runs on this page. Open the complete example in Rust Playground to edit, compile, and run it.</p></div></div>`;
 root.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{clearInterval(timer);playing=false;current=examples.find(e=>e.id===b.dataset.example);frame=0;renderTrace()});
 root.querySelector('#trace-next').onclick=()=>{pause();frame=Math.min(frame+1,current.frames.length-1);paintTrace()};root.querySelector('#trace-back').onclick=()=>{pause();frame=Math.max(0,frame-1);paintTrace()};root.querySelector('#trace-reset').onclick=()=>{pause();frame=0;paintTrace()};
 root.querySelector('#trace-play').onclick=()=>{if(playing){pause();paintTrace();return}if(frame===current.frames.length-1)frame=0;playing=true;paintTrace();timer=setInterval(()=>{if(!root)return;frame=Math.min(frame+1,current.frames.length-1);if(frame===current.frames.length-1)pause();paintTrace()},1400)};paintTrace();
}
function pause(){clearInterval(timer);playing=false;}
function paintTrace(){if(!root)return;const f=current.frames[frame];root.querySelector('#trace-code').innerHTML=current.code.split('\n').map((line,i)=>`<span class="code-line ${i+1===f.line?'current':''}"><span class="line-number">${i+1}</span><code>${esc(line)||' '}</code></span>`).join('');root.querySelector('#trace-back').disabled=frame===0;root.querySelector('#trace-next').disabled=frame===current.frames.length-1;root.querySelector('#trace-play').innerHTML=icon(playing?'pause':'play');root.querySelector('#trace-play').setAttribute('aria-label',playing?'Pause trace':'Play trace');
 root.querySelector('#memory-view').innerHTML=`<div class="memory-heading"><span>Bindings</span><span>${f.bindings.length} tracked</span></div><div class="binding-list">${f.bindings.map(b=>`<div class="binding ${b.status}"><div><strong>${esc(b.name)}</strong><small>${esc(b.value)}</small></div><div class="binding-target">${b.target?`<span class="allocation-link">${b.status==='shared'?'&':b.status==='exclusive'?'&mut':'owns'} ${b.target}</span>`:''}<span class="state-tag">${esc(b.status)}</span></div></div>`).join('')}</div><div class="memory-heading"><span>Heap allocations</span><span>symbolic labels</span></div><div class="heap-list">${f.heap.length?f.heap.map(h=>`<div class="heap-block ${h.alive?'':'released'}"><b>${h.id}</b><code>"${esc(h.value)}"</code><small>${h.alive?'allocated':'released'}</small></div>`).join(''):'<div class="heap-empty">No heap allocation in this example.</div>'}</div>`;
 root.querySelector('#trace-explanation').innerHTML=`<div class="eyebrow">${current.error?'COMPILER REASONING':'TRACE'} · ${frame+1} / ${current.frames.length}</div><h2>${esc(f.title)}</h2><p>${esc(f.body)}</p><div class="trace-dots">${current.frames.map((_,i)=>`<button data-frame="${i}" class="${i===frame?'active':''}" aria-label="Trace step ${i+1}">${i+1}</button>`).join('')}</div>`;
 root.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{pause();frame=Number(b.dataset.frame);paintTrace()});root.querySelector('#trace-output').textContent=current.error?`error[${current.error}]: ${current.diagnostic}\n\nThis program is rejected before execution.`:f.output||'No output yet.';
}
function renderIterator(){root.querySelector('#lab-body').innerHTML=`<div class="trace-layout"><aside class="lab-controls"><h2>${icon('signal')} Pipeline settings</h2><div class="control"><label for="iterator-input">Input integers</label><textarea id="iterator-input" class="data-input" rows="3">1, 2, 3, 4, 5, 6</textarea><small>Comma-separated · up to 24 values</small></div><div class="control"><label for="iterator-filter">Filter</label><div class="select-wrap"><select id="iterator-filter"><option value="even">Keep even values</option><option value="positive">Keep positive values</option><option value="all">Keep everything</option></select></div></div><div class="control"><label for="iterator-map">Map</label><div class="select-wrap"><select id="iterator-map"><option value="double">Multiply by 2</option><option value="square">Square each value</option><option value="increment">Add 1</option></select></div></div><div class="control"><label for="iterator-consumer">Consume</label><div class="select-wrap"><select id="iterator-consumer"><option value="collect">Collect into a Vec</option><option value="sum">Sum the values</option></select></div></div><button class="btn primary" id="evaluate-pipeline">${icon('play')} Evaluate pipeline</button><div class="input-error" id="iterator-error" role="alert"></div><a class="btn" id="iterator-playground" target="_blank" rel="noopener noreferrer">${icon('code')} Rust Playground</a></aside><div class="lab-content"><div class="trace-toolbar"><div class="compiler-state accepted">${icon('signal')} Interactive value transformation</div><span class="engine-indicator">Browser calculation</span></div><section class="plot-card"><div class="panel-heading"><span>${icon('rows')} Follow the values</span><small>filter · map · consume</small></div><div class="pipeline-view" id="pipeline-view"></div></section><section class="plot-card" style="margin-top:16px"><div class="panel-heading"><span>${icon('code')} Equivalent Rust program</span><small>main.rs</small></div><pre class="pipeline-code" id="pipeline-code"></pre></section><p class="lab-explanation">Rust iterator adapters are lazy: the consumer requests items and drives filtering and mapping. The rows above show the conceptual values at each stage; Rust does not need to allocate those intermediate collections.</p><p class="query-note">This bounded integer pipeline is evaluated in JavaScript. Open the generated Rust program in Rust Playground to compile and run it.</p></div></div>`;root.querySelector('#evaluate-pipeline').onclick=evaluatePipeline;root.querySelectorAll('select').forEach(s=>s.onchange=evaluatePipeline);evaluatePipeline();}
function evaluatePipeline(){try{pipeline=iteratorExperiment(root.querySelector('#iterator-input').value,root.querySelector('#iterator-filter').value,root.querySelector('#iterator-map').value,root.querySelector('#iterator-consumer').value);root.querySelector('#iterator-error').textContent='';root.querySelector('#iterator-playground').href=playgroundURL(pipeline.code);root.querySelector('#download-rust').disabled=false;root.querySelector('#pipeline-code').textContent=pipeline.code;root.querySelector('#pipeline-view').innerHTML=[['Input',pipeline.input,'orange'],['After filter',pipeline.filtered,'violet'],['After map',pipeline.mapped,'green'],['Result',Array.isArray(pipeline.result)?pipeline.result:[pipeline.result],'green']].map(([label,values,color],i)=>`<div class="pipeline-row"><div class="pipeline-label"><span>${label}</span><small>${i===3?root.querySelector('#iterator-consumer').value:values.length+' values'}</small></div><div class="value-chips">${values.length?values.map(v=>`<span style="background:var(--${color})">${v}</span>`).join(''):'<em>empty</em>'}</div></div>`).join('')}catch(e){pipeline=null;root.querySelector('#iterator-error').textContent=e.message;root.querySelector('#iterator-playground').removeAttribute('href');root.querySelector('#download-rust').disabled=true;root.querySelector('#pipeline-view').innerHTML='<div class="empty-state">Correct the input to evaluate the pipeline.</div>';root.querySelector('#pipeline-code').textContent='';}}
